.project-row button { flex-shrink: 0; }
#back { margin-bottom: 24px; }
[role="alert"] { color: #b91c1c; }
[hidden] { display: none !important; }
@media (max-width: 600px) {
  main { margin: 20px 12px; padding: 20px; }
